// Fast paths, after the mimalloc technical report (simplified)
void* malloc_small(size_t n) {               // 0 < n <= 1024
  heap_t*  heap  = tlb;                      // thread-local heap
  page_t*  page  = heap->pages_direct[(n + 7) >> 3];
  block_t* block = page->free;
  if (block == NULL) return malloc_generic(heap, n);  // slow path
  page->free = block->next;
  page->used++;
  return block;
}

void free(void* p) {
  segment_t* seg  = (segment_t*)((uintptr_t)p & ~(SEGMENT_SIZE - 1));
  page_t*    page = &seg->pages[((uintptr_t)p - (uintptr_t)seg) >> seg->page_shift];
  block_t*   b    = (block_t*)p;
  if (thread_id() == seg->thread_id) {       // local free: plain stores
    b->next = page->local_free;
    page->local_free = b;
    page->used--;
  } else {                                   // remote free: one CAS loop
    atomic_push(&page->thread_free, b);
  }
}
